\\u0d9a\\u0dbb\\u0d9c\\u0db1\\u0dca\\u0db1 \\u0daf\\u0dd0\\u0db1\\u0dca\\u0db8 Ontech Advanced ERP & Accounting \\u0db4\\u0daf\\u0dca\\u0db0\\u0dad\\u0dd2\\u0dba\\u0da7 \\u0db8\\u0dcf\\u0dbb\\u0dd4 \\u0dc0\\u0dd9\\u0db1\\u0dca\\u0db1! \\ud83d\\ude80\\n\\n\\u0d85\\u0db1\\u0dd4\\u0db8\\u0dcf\\u0db1 \\u0d9a\\u0dbb\\u0dbd\\u0dcf \\u0dc0\\u0dd0\\u0dbb\\u0daf\\u0dd2 \\u0dad\\u0dd3\\u0dbb\\u0dab \\u0d9c\\u0db1\\u0dca\\u0db1 \\u0d91\\u0d9a \\u0daf\\u0dd0\\u0db1\\u0dca\\u0db8 \\u0db1\\u0dc0\\u0dad\\u0dca\\u0dc0\\u0db1\\u0dca\\u0db1. \\u0db1\\u0dd2\\u0dc0\\u0dd0\\u0dbb\\u0daf\\u0dd2 \\u0daf\\u0dad\\u0dca\\u0dad \\u0db8\\u0dad \\u0db4\\u0daf\\u0db1\\u0db8\\u0dca\\u0dc0, \\u0d9a\\u0dd2\\u0dc3\\u0dd2\\u0db8 \\u0d85\\u0da9\\u0dd4\\u0dc0\\u0d9a\\u0dca \\u0db1\\u0dd0\\u0dad\\u0dd4\\u0dc0 \\u0d94\\u0db6\\u0dda \\u0dc0\\u0dca\\u200d\\u0dba\\u0dcf\\u0db4\\u0dcf\\u0dbb\\u0dba\\u0dda \\u0d9c\\u0dd2\\u0dab\\u0dd4\\u0db8\\u0dca \\u0d9a\\u0da7\\u0dba\\u0dd4\\u0dad\\u0dd4 \\u0dc3\\u0dd2\\u0dba\\u0dbd\\u0dca\\u0dbd\\u0db8 \\u0d91\\u0d9a\\u0db8 \\u0dad\\u0dd0\\u0db1\\u0d9a\\u0dd2\\u0db1\\u0dca \\u0db4\\u0dc4\\u0dc3\\u0dd4\\u0dc0\\u0dd9\\u0db1\\u0dca \\u0d9a\\u0dc5\\u0db8\\u0db1\\u0dcf\\u0d9a\\u0dbb\\u0dab\\u0dba \\u0d9a\\u0dbb\\u0d9c\\u0db1\\u0dca\\u0db1 \\u0d85\\u0db4\\u0dd2 \\u0d94\\u0db6\\u0da7 \\u0d8b\\u0daf\\u0dc0\\u0dca \\u0d9a\\u0dbb\\u0db1\\u0dc0\\u0dcf.\\n\\nOntech ERP \\u0db8\\u0dd8\\u0daf\\u0dd4\\u0d9a\\u0dcf\\u0d82\\u0d9c\\u0dba \\u0dc4\\u0dbb\\u0dc4\\u0dcf \\u0d94\\u0db6\\u0da7 \\u0dbd\\u0dd0\\u0db6\\u0dd9\\u0db1 \\u0dc3\\u0dd4\\u0dc0\\u0dd2\\u0dc1\\u0dda\\u0dc2\\u0dd3 \\u0dc0\\u0dcf\\u0dc3\\u0dd2:\\n\\n\\u2705 \\u0d91\\u0dc3\\u0dd0\\u0dab\\u0dd2\\u0db1\\u0dca \\u0dc1\\u0dd4\\u0daf\\u0dca\\u0db0 \\u0dbd\\u0dcf\\u0db7\\u0dba (Instant Net Profit): \\u0db8\\u0dcf\\u0dc3\\u0dba \\u0d85\\u0dc0\\u0dc3\\u0db1\\u0dca \\u0dc0\\u0db1\\u0dad\\u0dd4\\u0dbb\\u0dd4 \\u0db6\\u0dbd\\u0dcf \\u0db1\\u0ddc\\u0dc3\\u0dd2\\u0da7, \\u0d95\\u0db1\\u0dd1\\u0db8 \\u0db8\\u0ddc\\u0dc4\\u0ddc\\u0dad\\u0d9a \\u0dc0\\u0dca\\u200d\\u0dba\\u0dcf\\u0db4\\u0dcf\\u0dbb\\u0dba\\u0dda \\u0dc3\\u0dd0\\u0db6\\u0dd1 \\u0dbd\\u0dcf\\u0db7\\u0dba \\u0dc4\\u0ddd \\u0db4\\u0dcf\\u0da9\\u0dd4\\u0dc0 \\u0db1\\u0dd2\\u0dc0\\u0dd0\\u0dbb\\u0daf\\u0dd2\\u0dc0 \\u0daf\\u0dd0\\u0db1\\u0d9c\\u0db1\\u0dca\\u0db1.\\n\\u2705 \\u0dc3\\u0db8\\u0dca\\u0db4\\u0dd6\\u0dbb\\u0dca\\u0dab \\u0db8\\u0dd6\\u0dbd\\u0dca\\u200d\\u0dba \\u0daf\\u0dbb\\u0dca\\u0dc1\\u0d9a\\u0dba (Financial Dashboard): \\u0dc0\\u0dca\\u200d\\u0dba\\u0dcf\\u0db4\\u0dcf\\u0dbb\\u0dba\\u0dda \\u0dc3\\u0db8\\u0dca\\u0db4\\u0dd6\\u0dbb\\u0dca\\u0dab \\u0db8\\u0dd4\\u0dbd\\u0dca\\u200d\\u0dba \\u0dad\\u0dad\\u0dca\\u0dc0\\u0dba \\u0d91\\u0d9a\\u0db8 \\u0dad\\u0dd2\\u0dbb\\u0dba\\u0d9a\\u0dd2\\u0db1\\u0dca (Dashboard) \\u0d89\\u0dad\\u0dcf \\u0dc3\\u0dbb\\u0dbd\\u0dc0 \\u0dc3\\u0dc4 \\u0db4\\u0dd0\\u0dc4\\u0dd0\\u0daf\\u0dd2\\u0dbd\\u0dd2\\u0dc0 \\u0d85\\u0dc0\\u0db6\\u0ddd\\u0db0 \\u0d9a\\u0dbb\\u0d9c\\u0db1\\u0dca\\u0db1.\\n\\u2705 \\u0d9a\\u0dca\\u200d\\u0dbb\\u0db8\\u0dcf\\u0db1\\u0dd4\\u0d9a\\u0dd6\\u0dbd \\u0da0\\u0dd9\\u0d9a\\u0dca\\u0db4\\u0dad\\u0dca \\u0d9a\\u0dc5\\u0db8\\u0db1\\u0dcf\\u0d9a\\u0dbb\\u0dab\\u0dba (PDC Management): \\u0da0\\u0dd9\\u0d9a\\u0dca\\u0db4\\u0dad\\u0dca \\u0db8\\u0dcf\\u0dbb\\u0dd4 \\u0dc0\\u0db1 \\u0daf\\u0dd2\\u0db1 \\u0db8\\u0d9f\\u0dc4\\u0dd0\\u0dbb\\u0dd3\\u0db8 \\u0db1\\u0dd2\\u0dc3\\u0dcf \\u0dc3\\u0dd2\\u0daf\\u0dd4\\u0dc0\\u0db1 \\u0db4\\u0dcf\\u0da9\\u0dd4 \\u0dc3\\u0dc4 \\u0d85\\u0db4\\u0dc4\\u0dc3\\u0dd4\\u0dad\\u0dcf \\u0db8\\u0d9f\\u0dc4\\u0dbb\\u0dc0\\u0dcf \\u0d9c\\u0db1\\u0dca\\u0db1.\\n\\u2705 \\u0d8b\\u0dc3\\u0dc3\\u0dca \\u0d9c\\u0dd2\\u0dab\\u0dd4\\u0db8\\u0dca\\u0d9a\\u0dbb\\u0dab \\u0dc0\\u0dcf\\u0dbb\\u0dca\\u0dad\\u0dcf (Advanced Accounting): \\u0dc0\\u0dca\\u200d\\u0dba\\u0dcf\\u0db4\\u0dcf\\u0dbb\\u0dd2\\u0d9a \\u0dad\\u0dd3\\u0dbb\\u0dab \\u0d9c\\u0dd0\\u0db1\\u0dd3\\u0db8\\u0da7 \\u0d85\\u0dc0\\u0dc1\\u0dca\\u200d\\u0dba \\u0dc3\\u0dd2\\u0dba\\u0dbd\\u0dd4\\u0db8 \\u0db8\\u0dd6\\u0dbd\\u0dca\\u200d\\u0dba \\u0dc0\\u0dcf\\u0dbb\\u0dca\\u0dad\\u0dcf (Financial Reports) \\u0d9a\\u0dca\\u0dc2\\u0dab\\u0dba\\u0d9a\\u0dd2\\u0db1\\u0dca \\u0dbd\\u0db6\\u0dcf\\u0d9c\\u0db1\\u0dca\\u0db1.\\n\\u2705 \\u0db8\\u0dd2\\u0dbd\\u0daf\\u0dd3 \\u0d9c\\u0dd0\\u0db1\\u0dd3\\u0db8\\u0dca \\u0dc3\\u0dc4 \\u0dc0\\u0dd2\\u0dba\\u0daf\\u0db8\\u0dca \\u0db4\\u0dcf\\u0dbd\\u0db1\\u0dba (Purchase & Expense Tracking): \\u0d85\\u0db1\\u0dc0\\u0dc1\\u0dca\\u200d\\u0dba \\u0dc0\\u0dd2\\u0dba\\u0daf\\u0db8\\u0dca \\u0dc4\\u0db3\\u0dd4\\u0db1\\u0dcf\\u0d9c\\u0dd9\\u0db1 \\u0d92\\u0dc0\\u0dcf \\u0db4\\u0dcf\\u0dbd\\u0db1\\u0dba \\u0d9a\\u0dbb\\u0db1\\u0dca\\u0db1\\u0dad\\u0dca, \\u0d85\\u0db1\\u0dc0\\u0dc1\\u0dca\\u200d\\u0dba \\u0dad\\u0ddc\\u0d9c \\u0db8\\u0dd2\\u0dbd\\u0daf\\u0dd3 \\u0d9c\\u0dd0\\u0db1\\u0dd3\\u0db8\\u0dca \\u0db1\\u0dd2\\u0dc3\\u0dcf \\u0db8\\u0dd4\\u0daf\\u0dbd\\u0dca \\u0dc4\\u0dd2\\u0dbb\\u0dc0\\u0dd3\\u0db8 (Cashflow issues) \\u0dc0\\u0dc5\\u0d9a\\u0dca\\u0dc0\\u0dcf \\u0d9c\\u0db1\\u0dca\\u0db1\\u0dad\\u0dca \\u0db8\\u0dd9\\u0dba \\u0d9a\\u0daf\\u0dd2\\u0db8 \\u0dc0\\u0dd2\\u0dc3\\u0db3\\u0dd4\\u0db8\\u0d9a\\u0dd2.\\n\\n\\u0d85\\u0daf\\u0db8 \\u0d94\\u0db6\\u0dda \\u0dc0\\u0dca\\u200d\\u0dba\\u0dcf\\u0db4\\u0dcf\\u0dbb\\u0dba \\u0da9\\u0dd2\\u0da2\\u0dd2\\u0da7\\u0dbd\\u0dca\\u0d9a\\u0dbb\\u0dab\\u0dba \\u0d9a\\u0dbb, \\u0daf\\u0dd2\\u0db1\\u0dd9\\u0db1\\u0dca \\u0daf\\u0dd2\\u0db1 \\u0dc3\\u0dcf\\u0dbb\\u0dca\\u0dae\\u0d9a\\u0dad\\u0dca\\u0dc0\\u0dba \\u0d9a\\u0dbb\\u0dcf \\u0db4\\u0dd2\\u0dba\\u0db1\\u0d9c\\u0db1\\u0dca\\u0db1! \\ud83d\\udcc8\\ud83d\\udcbc\\n\\n\\u0dc0\\u0dd0\\u0da9\\u0dd2 \\u0dc0\\u0dd2\\u0dc3\\u0dca\\u0dad\\u0dbb \\u0dc3\\u0db3\\u0dc4\\u0dcf \\u0d85\\u0daf\\u0db8 \\u0d85\\u0db4\\u0dc0 \\u0d85\\u0db8\\u0dad\\u0db1\\u0dca\\u0db1:\\n\\u260e\\ufe0f Call \\/ WhatsApp: 077 2513161\\n\\ud83c\\udf10 Web: www.ontechsl.com\\n\\n#OntechSL #ERP #AccountingSoftware #BusinessManagement #SmallBusinessSL #SriLankaBusiness #ProfitManagement #FinancialFreedom #OntechSriLanka #BusinessGrowth\",\"headline\":\"Ontech Sri Lanka\",\"media_type\":\"image\",\"image_url\":\"https:\\/\\/scontent-bom5-2.xx.fbcdn.net\\/v\\/t39.30808-6\\/647591641_1396751472469974_8775459488012328832_n.jpg?stp=dst-jpg_e48_fr_q75_tt6&cstp=mx1024x1024&ctp=s851x315&_nc_cat=111&ccb=1-7&_nc_sid=c8f752&_nc_ohc=1PlojoutUNcQ7kNvwGeg-Bq&_nc_oc=AdoWh_vVX_5Rdp4UoCbT6C0nQ6qfKPe8UVEiKHtLc3LTeuN76_2SXmJEC6paqiklEXU&_nc_ad=z-m&_nc_cid=1228&_nc_zt=23&_nc_ht=scontent-bom5-2.xx&_nc_ss=7a3ba&oh=00_AQL-itv_w0YlV91PRL0mJChAFAk2zyizG4utFoFG_Np25Q&oe=6ABB4FCC\",\"ctwa_clid\":\"AfgwmWvjthb1vblxWdOd1cra1TLQBGiQwKpndWOV1Ac_B6WGQxmic7Bcu04It4508YeAN9TPe6GM_Xd3qJXvvEHg1-2LfyKpGcElfTj_Y6HnTUOR3w3_8S6gJZGzL7uGH5kR6kUGiQ\",\"welcome_message\":{\"text\":\"Hi! \\ud83d\\udc4b Welcome to Ontech Software Solutions. Ask us anything about our ERP & Accounting system!\"}},\"from\":\"94757777984\",\"from_user_id\":\"LK.1141850575083105\",\"id\":\"wamid.HBgLOTQ3NTc3Nzc5ODQVAgASGBQzQTk2QkJERkExQ0FBRkIyODNDMwA=\",\"timestamp\":\"1790272352\",\"text\":{\"body\":\"Can I get a free demo of Ontech ERP & Accounting? [REF:ERP-FB-01]\"},\"type\":\"text\"}]},\"field\":\"messages\"}]}]}', '2026-09-24 17:52:33', '2026-09-24 17:52:33');
