da \\u0db4\\u0dcf\\u0dbd\\u0db1\\u0dba\\u0da7 \\u0db1\\u0dad\\u0dd4 \\u0d9a\\u0dbb\\u0d9c\\u0db1\\u0dca\\u0db1 \\u0daf\\u0dd0\\u0db1\\u0dca\\u0db8 Ontech Advanced ERP & Accounting \\u0db4\\u0daf\\u0dca\\u0db0\\u0dad\\u0dd2\\u0dba\\u0da7 \\u0db8\\u0dcf\\u0dbb\\u0dd4 \\u0dc0\\u0dd9\\u0db1\\u0dca\\u0db1! \\ud83d\\ude80\\n\\n\\u0d85\\u0db1\\u0dd4\\u0db8\\u0dcf\\u0db1 \\u0d9a\\u0dbb\\u0dbd\\u0dcf \\u0dc0\\u0dd0\\u0dbb\\u0daf\\u0dd2 \\u0dad\\u0dd3\\u0dbb\\u0dab \\u0d9c\\u0db1\\u0dca\\u0db1 \\u0d91\\u0d9a \\u0daf\\u0dd0\\u0db1\\u0dca\\u0db8 \\u0db1\\u0dc0\\u0dad\\u0dca\\u0dc0\\u0db1\\u0dca\\u0db1. \\u0db1\\u0dd2\\u0dc0\\u0dd0\\u0dbb\\u0daf\\u0dd2 \\u0daf\\u0dad\\u0dca\\u0dad \\u0db8\\u0dad \\u0db4\\u0daf\\u0db1\\u0db8\\u0dca\\u0dc0, \\u0d9a\\u0dd2\\u0dc3\\u0dd2\\u0db8 \\u0d85\\u0da9\\u0dd4\\u0dc0\\u0d9a\\u0dca \\u0db1\\u0dd0\\u0dad\\u0dd4\\u0dc0 \\u0d94\\u0db6\\u0dda \\u0dc0\\u0dca\\u200d\\u0dba\\u0dcf\\u0db4\\u0dcf\\u0dbb\\u0dba\\u0dda \\u0d9c\\u0dd2\\u0dab\\u0dd4\\u0db8\\u0dca \\u0d9a\\u0da7\\u0dba\\u0dd4\\u0dad\\u0dd4 \\u0dc3\\u0dd2\\u0dba\\u0dbd\\u0dca\\u0dbd\\u0db8 \\u0d91\\u0d9a\\u0db8 \\u0dad\\u0dd0\\u0db1\\u0d9a\\u0dd2\\u0db1\\u0dca \\u0db4\\u0dc4\\u0dc3\\u0dd4\\u0dc0\\u0dd9\\u0db1\\u0dca \\u0d9a\\u0dc5\\u0db8\\u0db1\\u0dcf\\u0d9a\\u0dbb\\u0dab\\u0dba \\u0d9a\\u0dbb\\u0d9c\\u0db1\\u0dca\\u0db1 \\u0d85\\u0db4\\u0dd2 \\u0d94\\u0db6\\u0da7 \\u0d8b\\u0daf\\u0dc0\\u0dca \\u0d9a\\u0dbb\\u0db1\\u0dc0\\u0dcf.\\n\\nOntech ERP \\u0db8\\u0dd8\\u0daf\\u0dd4\\u0d9a\\u0dcf\\u0d82\\u0d9c\\u0dba \\u0dc4\\u0dbb\\u0dc4\\u0dcf \\u0d94\\u0db6\\u0da7 \\u0dbd\\u0dd0\\u0db6\\u0dd9\\u0db1 \\u0dc3\\u0dd4\\u0dc0\\u0dd2\\u0dc1\\u0dda\\u0dc2\\u0dd3 \\u0dc0\\u0dcf\\u0dc3\\u0dd2:\\n\\n\\u2705 \\u0d91\\u0dc3\\u0dd0\\u0dab\\u0dd2\\u0db1\\u0dca \\u0dc1\\u0dd4\\u0daf\\u0dca\\u0db0 \\u0dbd\\u0dcf\\u0db7\\u0dba (Instant Net Profit): \\u0db8\\u0dcf\\u0dc3\\u0dba \\u0d85\\u0dc0\\u0dc3\\u0db1\\u0dca \\u0dc0\\u0db1\\u0dad\\u0dd4\\u0dbb\\u0dd4 \\u0db6\\u0dbd\\u0dcf \\u0db1\\u0ddc\\u0dc3\\u0dd2\\u0da7, \\u0d95\\u0db1\\u0dd1\\u0db8 \\u0db8\\u0ddc\\u0dc4\\u0ddc\\u0dad\\u0d9a \\u0dc0\\u0dca\\u200d\\u0dba\\u0dcf\\u0db4\\u0dcf\\u0dbb\\u0dba\\u0dda \\u0dc3\\u0dd0\\u0db6\\u0dd1 \\u0dbd\\u0dcf\\u0db7\\u0dba \\u0dc4\\u0ddd \\u0db4\\u0dcf\\u0da9\\u0dd4\\u0dc0 \\u0db1\\u0dd2\\u0dc0\\u0dd0\\u0dbb\\u0daf\\u0dd2\\u0dc0 \\u0daf\\u0dd0\\u0db1\\u0d9c\\u0db1\\u0dca\\u0db1.\\n\\u2705 \\u0dc3\\u0db8\\u0dca\\u0db4\\u0dd6\\u0dbb\\u0dca\\u0dab \\u0db8\\u0dd6\\u0dbd\\u0dca\\u200d\\u0dba \\u0daf\\u0dbb\\u0dca\\u0dc1\\u0d9a\\u0dba (Financial Dashboard): \\u0dc0\\u0dca\\u200d\\u0dba\\u0dcf\\u0db4\\u0dcf\\u0dbb\\u0dba\\u0dda \\u0dc3\\u0db8\\u0dca\\u0db4\\u0dd6\\u0dbb\\u0dca\\u0dab \\u0db8\\u0dd4\\u0dbd\\u0dca\\u200d\\u0dba \\u0dad\\u0dad\\u0dca\\u0dc0\\u0dba \\u0d91\\u0d9a\\u0db8 \\u0dad\\u0dd2\\u0dbb\\u0dba\\u0d9a\\u0dd2\\u0db1\\u0dca (Dashboard) \\u0d89\\u0dad\\u0dcf \\u0dc3\\u0dbb\\u0dbd\\u0dc0 \\u0dc3\\u0dc4 \\u0db4\\u0dd0\\u0dc4\\u0dd0\\u0daf\\u0dd2\\u0dbd\\u0dd2\\u0dc0 \\u0d85\\u0dc0\\u0db6\\u0ddd\\u0db0 \\u0d9a\\u0dbb\\u0d9c\\u0db1\\u0dca\\u0db1.\\n\\u2705 \\u0d9a\\u0dca\\u200d\\u0dbb\\u0db8\\u0dcf\\u0db1\\u0dd4\\u0d9a\\u0dd6\\u0dbd \\u0da0\\u0dd9\\u0d9a\\u0dca\\u0db4\\u0dad\\u0dca \\u0d9a\\u0dc5\\u0db8\\u0db1\\u0dcf\\u0d9a\\u0dbb\\u0dab\\u0dba (PDC Management): \\u0da0\\u0dd9\\u0d9a\\u0dca\\u0db4\\u0dad\\u0dca \\u0db8\\u0dcf\\u0dbb\\u0dd4 \\u0dc0\\u0db1 \\u0daf\\u0dd2\\u0db1 \\u0db8\\u0d9f\\u0dc4\\u0dd0\\u0dbb\\u0dd3\\u0db8 \\u0db1\\u0dd2\\u0dc3\\u0dcf \\u0dc3\\u0dd2\\u0daf\\u0dd4\\u0dc0\\u0db1 \\u0db4\\u0dcf\\u0da9\\u0dd4 \\u0dc3\\u0dc4 \\u0d85\\u0db4\\u0dc4\\u0dc3\\u0dd4\\u0dad\\u0dcf \\u0db8\\u0d9f\\u0dc4\\u0dbb\\u0dc0\\u0dcf \\u0d9c\\u0db1\\u0dca\\u0db1.\\n\\u2705 \\u0d8b\\u0dc3\\u0dc3\\u0dca \\u0d9c\\u0dd2\\u0dab\\u0dd4\\u0db8\\u0dca\\u0d9a\\u0dbb\\u0dab \\u0dc0\\u0dcf\\u0dbb\\u0dca\\u0dad\\u0dcf (Advanced Accounting): \\u0dc0\\u0dca\\u200d\\u0dba\\u0dcf\\u0db4\\u0dcf\\u0dbb\\u0dd2\\u0d9a \\u0dad\\u0dd3\\u0dbb\\u0dab \\u0d9c\\u0dd0\\u0db1\\u0dd3\\u0db8\\u0da7 \\u0d85\\u0dc0\\u0dc1\\u0dca\\u200d\\u0dba \\u0dc3\\u0dd2\\u0dba\\u0dbd\\u0dd4\\u0db8 \\u0db8\\u0dd6\\u0dbd\\u0dca\\u200d\\u0dba \\u0dc0\\u0dcf\\u0dbb\\u0dca\\u0dad\\u0dcf (Financial Reports) \\u0d9a\\u0dca\\u0dc2\\u0dab\\u0dba\\u0d9a\\u0dd2\\u0db1\\u0dca \\u0dbd\\u0db6\\u0dcf\\u0d9c\\u0db1\\u0dca\\u0db1.\\n\\u2705 \\u0db8\\u0dd2\\u0dbd\\u0daf\\u0dd3 \\u0d9c\\u0dd0\\u0db1\\u0dd3\\u0db8\\u0dca \\u0dc3\\u0dc4 \\u0dc0\\u0dd2\\u0dba\\u0daf\\u0db8\\u0dca \\u0db4\\u0dcf\\u0dbd\\u0db1\\u0dba (Purchase & Expense Tracking): \\u0d85\\u0db1\\u0dc0\\u0dc1\\u0dca\\u200d\\u0dba \\u0dc0\\u0dd2\\u0dba\\u0daf\\u0db8\\u0dca \\u0dc4\\u0db3\\u0dd4\\u0db1\\u0dcf\\u0d9c\\u0dd9\\u0db1 \\u0d92\\u0dc0\\u0dcf \\u0db4\\u0dcf\\u0dbd\\u0db1\\u0dba \\u0d9a\\u0dbb\\u0db1\\u0dca\\u0db1\\u0dad\\u0dca, \\u0d85\\u0db1\\u0dc0\\u0dc1\\u0dca\\u200d\\u0dba \\u0dad\\u0ddc\\u0d9c \\u0db8\\u0dd2\\u0dbd\\u0daf\\u0dd3 \\u0d9c\\u0dd0\\u0db1\\u0dd3\\u0db8\\u0dca \\u0db1\\u0dd2\\u0dc3\\u0dcf \\u0db8\\u0dd4\\u0daf\\u0dbd\\u0dca \\u0dc4\\u0dd2\\u0dbb\\u0dc0\\u0dd3\\u0db8 (Cashflow issues) \\u0dc0\\u0dc5\\u0d9a\\u0dca\\u0dc0\\u0dcf \\u0d9c\\u0db1\\u0dca\\u0db1\\u0dad\\u0dca \\u0db8\\u0dd9\\u0dba \\u0d9a\\u0daf\\u0dd2\\u0db8 \\u0dc0\\u0dd2\\u0dc3\\u0db3\\u0dd4\\u0db8\\u0d9a\\u0dd2.\\n\\n\\u0d85\\u0daf\\u0db8 \\u0d94\\u0db6\\u0dda \\u0dc0\\u0dca\\u200d\\u0dba\\u0dcf\\u0db4\\u0dcf\\u0dbb\\u0dba \\u0da9\\u0dd2\\u0da2\\u0dd2\\u0da7\\u0dbd\\u0dca\\u0d9a\\u0dbb\\u0dab\\u0dba \\u0d9a\\u0dbb, \\u0daf\\u0dd2\\u0db1\\u0dd9\\u0db1\\u0dca \\u0daf\\u0dd2\\u0db1 \\u0dc3\\u0dcf\\u0dbb\\u0dca\\u0dae\\u0d9a\\u0dad\\u0dca\\u0dc0\\u0dba \\u0d9a\\u0dbb\\u0dcf \\u0db4\\u0dd2\\u0dba\\u0db1\\u0d9c\\u0db1\\u0dca\\u0db1! \\ud83d\\udcc8\\ud83d\\udcbc\\n\\n\\u0dc0\\u0dd0\\u0da9\\u0dd2 \\u0dc0\\u0dd2\\u0dc3\\u0dca\\u0dad\\u0dbb \\u0dc3\\u0db3\\u0dc4\\u0dcf \\u0d85\\u0daf\\u0db8 \\u0d85\\u0db4\\u0dc0 \\u0d85\\u0db8\\u0dad\\u0db1\\u0dca\\u0db1:\\n\\u260e\\ufe0f Call \\/ WhatsApp: 077 2513161\\n\\ud83c\\udf10 Web: www.ontechsl.com\\n\\n#OntechSL #ERP #AccountingSoftware #BusinessManagement #SmallBusinessSL #SriLankaBusiness #ProfitManagement #FinancialFreedom #OntechSriLanka #BusinessGrowth\",\"headline\":\"Ontech Sri Lanka\",\"media_type\":\"image\",\"image_url\":\"https:\\/\\/scontent.fcmb8-1.fna.fbcdn.net\\/v\\/t39.30808-6\\/647591641_1396751472469974_8775459488012328832_n.jpg?stp=cp0_dst-jpg_e48_fr_q65_tt6&cstp=mx1024x1024&ctp=s320x320&_nc_cat=111&_nc_map=urlgen_bucketless&ccb=1-7&_nc_sid=c8f752&_nc_ohc=1PlojoutUNcQ7kNvwEgKD7Z&_nc_oc=Adqf_v_fgzr3hHfzv556qDspsAmVn0Nj61UXprsF1mmhlEfFXbIdtBFybQz-rcVsucQ&_nc_ad=z-m&_nc_cid=1157&_nc_zt=23&_nc_ht=scontent.fcmb8-1.fna&_nc_ss=7a3ba&oh=00_AQKT2bnhz-ughviGlGDdhvpwPBTLKbhvN5awPo2JoJ50xg&oe=6ABBF88C\",\"ctwa_clid\":\"AfghiDcDzWhTphSJkjvTBKLGiAD5mMyG69HRi3siXTCWxeFXEuZ2pbFfI3i5IUjxkqwKavHg03Cx8seAuoyP-1XKW43x9dm0T8aVzU21IE3byL1do--v-H4hvhZuYqpHGaOFzbGpLQ\",\"welcome_message\":{\"text\":\"Hi! \\ud83d\\udc4b Welcome to Ontech Software Solutions. Ask us anything about our ERP & Accounting system!\"}},\"from\":\"94715539187\",\"from_user_id\":\"LK.1106788941808675\",\"id\":\"wamid.HBgLOTQ3MTU1MzkxODcVAgASGCBBQzg5QUVEM0VEQjlENDg0RTUzQTM4NzI4NUFFRDlDQwA=\",\"timestamp\":\"1790315702\",\"text\":{\"body\":\"Can I get a free demo of Ontech ERP & Accounting? [REF:ERP-FB-01]\"},\"type\":\"text\"}]},\"field\":\"messages\"}]}]}', '2026-09-25 05:55:04', '2026-09-25 05:55:04'),
(59, 'wamid.HBgLOTQ3NzM0MzQ4MzQVAgASGCBBQ0E1RDRDMzIyMjBGNkRCNTExQkE5QjFGQ0I4MzQwNgA=', '94773434834', 'Vvip', 'incoming', 'text', 'Normal Chat', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Hello,\n\nI am from Miracle Bio Green (Pvt) Ltd. We are looking for an ERP system to manage our dealer network and daily business operations.\n\nWe currently have more than 400 dealers, and we need a system that can manage the following:\n\n• Dealer-wise outstanding balances\n• Credit limits and credit periods\n• Sales invoices and payment history\n• Stock management for 1L, 500ml and 250ml products\n• Sales returns and damaged stock\n• Post-dated cheque tracking\n• Customer and dealer payment collections\n• Courier COD orders with waybill numbers\n• COD pending settlements, received payments and returned parcels\n• Owner dashboard with sales, stock, outstanding and collections\n• Separate restricted login access for office staff\n• Mobile and computer access\n• Excel/PDF reports\n\nWe would also like the stock balance and dealer outstanding to update automatically when invoices, payments or returns are entered.\n\nCould you please arrange a free demo and let us know whether Chart360 can be customized according to these requirements?\n\nPlease also provide us with your implementation cost, annual charges and customization charges.\n\nThank you.\n\nMiracle Bio Green (Pvt) Ltd.', 'received', '693326623870717', '2026-09-25 06:30:22', '2026-09-25 06:30:22', '{\"object\":\"whatsapp_business_account\",\"entry\":[{\"id\":\"1954675295363983\",\"changes\":[{\"value\":{\"messaging_product\":\"whatsapp\",\"metadata\":{\"display_phone_number\":\"94706513161\",\"phone_number_id\":\"693326623870717\"},\"contacts\":[{\"profile\":{\"name\":\"Vvip\"},\"wa_id\":\"94773434834\",\"user_id\":\"LK.1425779546222444\"}],\"messages\":[{\"from\":\"94773434834\",\"from_user_id\":\"LK.1425779546222444\",\"id\":\"wamid.HBgLOTQ3NzM0MzQ4MzQVAgASGCBBQ0E1RDRDMzIyMjBGNkRCNTExQkE5QjFGQ0I4MzQwNgA=\",\"timestamp\":\"1790317822\",\"text\":{\"body\":\"Hello,\\n\\nI am from Miracle Bio Green (Pvt) Ltd. We are looking for an ERP system to manage our dealer network and daily business operations.\\n\\nWe currently have more than 400 dealers, and we need a system that can manage the following:\\n\\n\\u2022 Dealer-wise outstanding balances\\n\\u2022 Credit limits and credit periods\\n\\u2022 Sales invoices and payment history\\n\\u2022 Stock management for 1L, 500ml and 250ml products\\n\\u2022 Sales returns and damaged stock\\n\\u2022 Post-dated cheque tracking\\n\\u2022 Customer and dealer payment collections\\n\\u2022 Courier COD orders with waybill numbers\\n\\u2022 COD pending settlements, received payments and returned parcels\\n\\u2022 Owner dashboard with sales, stock, outstanding and collections\\n\\u2022 Separate restricted login access for office staff\\n\\u2022 Mobile and computer access\\n\\u2022 Excel\\/PDF reports\\n\\nWe would also like the stock balance and dealer outstanding to update automatically when invoices, payments or returns are entered.\\n\\nCould you please arrange a free demo and let us know whether Chart360 can be customized according to these requirements?\\n\\nPlease also provide us with your implementation cost, annual charges and customization charges.\\n\\nThank you.\\n\\nMiracle Bio Green (Pvt) Ltd.\"},\"type\":\"text\"}]},\"field\":\"messages\"}]}]}', '2026-09-25 06:30:22', '2026-09-25 06:30:22'),
(60, 'wamid.HBgLOTQ3NzM0MzQ4MzQVAgASGCBBQzIwNUVEQUZGQ0YyN0ZENkZGOEU5NzdGMzczRTJBMwA=', '94773434834', 'Vvip', 'incoming', 'text', 'Ad - Flyer/Image', 1, 'ERP-FB-01', 'ERP', 'Facebook', NULL, NULL, NULL, 'Ontech Sri Lanka', '120249997146320479', 'https://fb.me/7YSdh5zw5', 'Fb', 'Ontech Sri Lanka', 'ව්‍යාපාරයේ ලාභය කීයද කියලා හරියටම දන්නේ නැද්ද? බැංකුවේ සල්ලි සහ අතේ තියෙන සල්ලි නිතරම පැටලෙනවාද? 🤔\n\nඔබේ ව්‍යාපාරයේ හැම රුපියලක්ම නිවැරදිව ඔබේ පාලනයට නතු කරගන්න දැන්ම Ontech Advanced ERP & Accounting පද්ධතියට මාරු වෙන්න! 🚀\n\nඅනුමාන කරලා වැරදි තීරණ ගන්න එක දැන්ම නවත්වන්න. නිවැරදි දත්ත මත පදනම්ව, කිසිම අඩුවක් නැතුව ඔබේ ව්‍යාපාරයේ ගිණුම් කටයුතු සියල්ලම එකම තැනකින් පහසුවෙන් කළමනාකරණය කරගන්න අපි ඔබට උදව් කරනවා.\n\nOntech ERP මෘදුකාංගය හරහා ඔබට ලැබෙන සුවිශේෂී වාසි:\n\n✅ එසැණින් ශුද්ධ ලාභය (Instant Net Profit): මාසය අවසන් වනතුරු බලා නොසිට, ඕනෑම මොහොතක ව්‍යාපාරයේ සැබෑ ලාභය හෝ පාඩුව නිවැරදිව දැනගන්න.\n✅ සම්පූර්ණ මූල්‍ය දර්ශකය (Financial Dashboard): ව්‍යාපාරයේ සම්පූර්ණ මුල්‍ය තත්වය එකම තිරයකින් (Dashboard) ඉතා සරලව සහ පැහැදිලිව අවබෝධ කරගන්න.\n✅ ක්‍රමානුකූල චෙක්පත් කළමනාකරණය (PDC Management): චෙක්පත් මාරු වන දින මඟහැරීම නිසා සිදුවන පාඩු සහ අපහසුතා මඟහරවා ගන්න.\n✅ උසස් ගිණුම්කරණ වාර්තා (Advanced Accounting): ව්‍යාපාරික තීරණ ගැනීමට අවශ්‍ය සියලුම මූල්‍ය වාර්තා (Financial Reports) ක්ෂණයකින් ලබාගන්න.\n✅ මිලදී ගැනීම් සහ වියදම් පාලනය (Purchase & Expense Tracking): අනවශ්‍ය වියදම් හඳුනාගෙන ඒවා පාලනය කරන්නත්, අනවශ්‍ය තොග මිලදී ගැනීම් නිසා මුදල් හිරවීම (Cashflow issues) වළක්වා ගන්නත් මෙය කදිම විසඳුමකි.\n\nඅදම ඔබේ ව්‍යාපාරය ඩිජිටල්කරණය කර, දිනෙන් දින සාර්ථකත්වය කරා පියනගන්න! 📈💼\n\nවැඩි විස්තර සඳහා අදම අපව අමතන්න:\n☎️ Call / WhatsApp: 077 2513161\n🌐 Web: www.ontechsl.com\n\n#OntechSL #ERP #AccountingSoftware #BusinessManagement #SmallBusinessSL #SriLankaBusiness #ProfitManagement #FinancialFreedom #OntechSriLanka #BusinessGrowth', 'image', 'https://scontent.fcmb2-2.fna.fbcdn.net/v/t39.30808-6/647591641_1396751472469974_8775459488012328832_n.jpg?stp=cp0_dst-jpg_e48_fr_q65_tt6&cstp=mx1024x1024&ct